fruits = ["apple", "banana", "cherry"]
for i, fruit in enumerate(fruits):
    print(f"{i}: {fruit}")

# break: stop as soon as we find 5
for i in range(10):
    if i == 5:
        print(f"found at {i}")
        break

# continue: skip odd numbers
for i in range(8):
    if i % 2 != 0:
        continue
    print(i)
